const reviewGrammar = (packs, title, challenge, practice) => ({
  ...grammar(title,
    'Dùng các mẫu đã học trong tình huống mới. Tự trả lời câu trắc nghiệm, điền từ rồi viết câu của bạn trước khi xem mẫu đối chiếu.',
    packs.map(item => item.formula).join(' • '),
    [packs[0].examples[0], packs[packs.length - 1].examples[1]],
    practice.questions, challenge),
  writing: practice.writing
});

